def search_target(nums, target):
    """
    Searches for a target value in a sorted array using recursion.

    Args:
        nums: A sorted list of integers.
        target: The integer to search for.

    Returns:
        The index of the target if found, otherwise -1.
    """
    def recursive_search(left, right):
        if left > right:
            return -1

        mid = (left + right) // 2

        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
            return recursive_search(mid + 1, right)
        else:
            return recursive_search(left, mid - 1)

    return recursive_search(0, len(nums) - 1)
